const body = $('Demande').first().json.body || {};
const row = ($('Lire la vidéo').first().json.data || [])[0];
if (!row) throw new Error('Vidéo inconnue : ' + body.video_id);
const src = ($input.first().json.data || []).find(s => s.channel_id === row.channel_id);
if (src && src.statut !== 'usable') throw new Error(`${row.source_nom} est en « ${src.statut} » : pas d'extrait de cette source (règle anti-strike). Le sujet peut être repris depuis une autre source.`);
return [{ json: { ...row, exclure: body.exclure || null } }];

const v = $('Infos vidéo').first().json;
const t = $('Transcrire').first().json;
// c = confiance moyenne de la transcription française (une phrase en wolof, bambara, lingala, anglais… transcrite en français a une confiance basse et un texte incohérent)
const phrases = (t.phrases || []).map(p => `[${p.start}-${p.end}|c${p.conf ?? '?'}] ${p.texte}`).join('\n');
const excl = v.exclure ? `\nNe reprends PAS le passage ${v.exclure[0]}-${v.exclure[1]} s (déjà proposé et refusé) : choisis un autre moment.` : '';
const system = `Tu es monteur vidéo pour « Impacteur Afrique », chaîne de Shorts qui diffuse les meilleurs moments de l'actualité africaine en français (politique, géopolitique, souveraineté, économie, société, diaspora ; dirigeants, opposants, intellectuels, journalistes, citoyens).
Objectif : faire le maximum de vues. Choisis le moment le plus fort, le plus partageable, celui qui fera réagir le public africain francophone et la diaspora.
Tu reçois la transcription horodatée (en secondes) d'une vidéo, avec pour chaque phrase la confiance de la transcription française (c0.00 à c1.00).
RÈGLE ABSOLUE — LANGUE : l'extrait doit être ENTIÈREMENT en français. Beaucoup de chaînes africaines mélangent le français avec le wolof, le bambara, le lingala, le dioula, l'anglais, etc. Ces passages apparaissent comme du texte incohérent ou des mots étrangers, souvent avec une confiance basse (< c0.80). N'inclus AUCUNE phrase qui n'est pas en français. Si aucun passage d'au moins 9 secondes n'est entièrement en français, réponds {"aucun": true, "raison": "langue : …"}.
Pour l'extrait :
- durée : entre 9 et 150 secondes, choisie selon le moment lui-même (clash, punchline : 10-20 s ; démonstration, raisonnement : jusqu'à 2 min 30). Ne rallonge jamais artificiellement, ne coupe pas un raisonnement en plein milieu ;
- compréhensible seul, sans contexte (le spectateur doit saisir l'enjeu en 3 secondes) ;
- commence au DÉBUT d'une phrase et finit à la FIN d'une phrase (utilise exactement les horodatages fournis) ;
- privilégie : clash, punchline, discours fort, contradiction, aveu, chiffre choc, émotion, analyse éclairante ;
- reste neutre : tu montres le moment, tu ne prends pas parti.
Propose aussi un titre à incruster (6 mots max, percutant, fidèle aux propos, sans majuscules partout) et une description YouTube courte (2 phrases + 3 hashtags, dont #Afrique).
Enfin, ANALYSE l'extrait choisi (l'extrait seul) avec exactement ces valeurs :
- intervenant : nom complet de la ou des personnes qui parlent (max 2, séparées par une virgule) ;
- type_intervenant : politique | expert | journaliste | citoyen | militant | autre ;
- notoriete : tres_connu | connu | peu_connu (auprès du public africain francophone) ;
- pays : pays africain principalement concerné (ou « plusieurs », « Afrique », « diaspora ») ;
- camp : pouvoir en place | opposition | AES/souverainistes | panafricanistes | France/Occident | Russie/Chine | institutions africaines | institutions internationales | société civile | plusieurs camps | non partisan ;
- sujet : l'événement précis, 8 mots max ;
- theme : souveraineté/Françafrique | sécurité/terrorisme | guerre/conflit | élections/démocratie | coup d'État/transition | économie/développement | monnaie/franc CFA | ressources/matières premières | géopolitique | migration/diaspora | société | santé | éducation | corruption/justice | religion | culture/sport | autre ;
- lien_actu : chaud | recent | froid ;
- signification : faible | moyen | fort (importance pour les sociétés africaines) ;
- type_moment : clash | moment_fort | moment_emouvant ;
- ton : colere | indignation | humour | ironie | gravite | emotion | calme ;
- accroche : phrase_choc | question | attaque | chiffre | demarrage_lent ;
- type_titre : citation | question | information | consequence | interpellation.
Réponds UNIQUEMENT en JSON : {"start": 0, "end": 0, "titre": "...", "description": "...", "raison": "...", "analyse": {"intervenant": "...", "type_intervenant": "...", "notoriete": "...", "pays": "...", "camp": "...", "sujet": "...", "theme": "...", "lien_actu": "...", "signification": "...", "type_moment": "...", "ton": "...", "accroche": "...", "type_titre": "..."}}`;
const user = `Vidéo : ${v.titre}\nSource : ${v.source_nom}\nPubliée le : ${v.publiee_le || '?'}\nAngle éditorial suggéré : ${v.angle || '-'}${excl}\n\nTranscription :\n${phrases}`;
return [{ json: { duree: t.duree_s, phrases: t.phrases || [], body: { model: 'claude-sonnet-4-5', max_tokens: 1500, system, messages: [{ role: 'user', content: user }] } } }];

const v = $('Infos vidéo').first().json;
const prep = $('Préparer la demande').first().json;
const duree = prep.duree;
const txt = ($input.first().json.content || []).map(c => c.text || '').join('');
let c;
try { c = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1)); } catch (e) { throw new Error('Choix Claude illisible : ' + txt.slice(0, 200)); }
const refus = raison => [{ json: { ok: false, video_id: v.video_id, source_nom: v.source_nom, titre_video: v.titre, raison } }];
if (c.aucun) return refus(c.raison || 'aucun passage entièrement en français');
let start = Math.max(0, +c.start), end = Math.min(+c.end, duree || +c.end);
if (!(end > start)) throw new Error('Intervalle invalide');
if (end - start > 155) end = start + 150;
// contrôle langue : confiance moyenne des phrases de l'extrait
const ph = (prep.phrases || []).filter(p => p.start >= start - 0.5 && p.end <= end + 0.5 && p.conf != null);
const mots = ph.reduce((s, p) => s + p.texte.split(' ').length, 0);
const conf = mots ? ph.reduce((s, p) => s + p.conf * p.texte.split(' ').length, 0) / mots : 1;
const faibles = ph.filter(p => p.conf < 0.6).length;
if (conf < 0.8 || faibles > Math.max(1, ph.length * 0.2)) return refus(`langue : transcription française peu fiable (confiance ${conf.toFixed(2)}, ${faibles} phrase(s) douteuse(s))`);
const a = c.analyse || {};
const analyse = { ...a, format: 'extrait_seul', chaine: v.source_nom, duree_s: Math.round(end - start), confiance_fr: Math.round(conf * 100) / 100 };
return [{ json: { ok: true, video_id: v.video_id, source_nom: v.source_nom, titre_video: v.titre, start, end, titre: c.titre, description: c.description, raison: c.raison, analyse } }];

const c = $('Choix du moment').first().json;
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const mmss = s => `${Math.floor(s/60)}:${String(Math.round(s%60)).padStart(2,'0')}`;
const _cap = `🌍 <b>Impacteur Afrique</b> — 🤖 <b>Short prêt, publication au prochain créneau (toutes les 6 h)</b>\n✂️ <b>${esc(c.titre)}</b>\n📺 ${esc(c.source_nom)} · ${mmss(c.start)} → ${mmss(c.end)} (${Math.round(c.end - c.start)} s)\n🧠 ${esc(c.raison)}\n\n📝 ${esc(c.description)}`;
return [{ json: { caption: _cap.length > 1020 ? _cap.slice(0, 1015) + '…' : _cap,
  cb_ok: `clip_ok|${c.video_id}`, cb_retry: `clip_retry|${c.video_id}|${Math.round(c.start)}|${Math.round(c.end)}`, cb_no: `clip_no|${c.video_id}` }, binary: $input.first().binary }];
